<?php require __DIR__.'/../config/functions.php'; ensure_install(); require_member(); $db=get_db(); $st=$db->prepare('SELECT * FROM members WHERE id=?'); $st->execute(array($_SESSION['member_id'])); $me=$st->fetch(); $logs=$db->prepare('SELECT * FROM model_logs WHERE member_id=? ORDER BY id DESC LIMIT 20'); $logs->execute(array($_SESSION['member_id'])); page_header('会员中心'); ?><div class="card"><h2>会员中心</h2><p>账号：<?php echo esc($me['email']?:$me['phone']); ?>　等级：<?php echo esc($me['level']); ?>　余额/积分：<?php echo (int)$me['credits']; ?></p><a href="chat.php">智能对话</a><a href="image.php">AI图片</a><a href="video.php">AI视频</a></div><div class="card wide"><h3>调用记录</h3><table><tr><th>时间</th><th>模型</th><th>消耗</th><th>状态</th></tr><?php foreach($logs as $r) echo '<tr><td>'.esc($r['created_at']).'</td><td>'.esc($r['model_type']).'</td><td>'.$r['cost'].'</td><td>'.esc($r['status']).'</td></tr>'; ?></table></div><?php page_footer(); ?>
